sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // BASIC TEST: Just show an alert to confirm onChange is working
    alert('onChange triggered! Field: ' + control.getName() + ', Old: ' + oldValue + ', New: ' + newValue);

    // Don't run during loading
    if (isLoading) {
        console.log('onChange: Skipping because isLoading is true');
        return;
    }

    // Don't run if value didn't change
    if (newValue == oldValue) {
        console.log('onChange: Skipping because value did not change');
        return;
    }

    // Simple test message
    g_form.showFieldMsg('stock_name', 'onChange script is working! You entered: ' + newValue, 'info');

    // Test AJAX call with very simple response
    console.log('Testing AJAX call to TradeBookUtils...');

    var ga = new GlideAjax('TradeBookUtils');
    ga.addParam('sysparm_name', 'test');
    ga.getXMLAnswer(function(answer) {
        console.log('AJAX Response received: ' + answer);
        g_form.showFieldMsg('stock_name', 'Server responded: ' + answer, 'info');
    });
}
